class Solution {
    public int minTimeToVisitAllPoints(int[][] points){
        int answer=0;
        for(int i=1;i<points.length;i++)answer+=Math.max(Math.abs(points[i][0]-points[i-1][0]),Math.abs(points[i][1]-points[i-1][1]));
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minTimeToVisitAllPoints(points:Array<IntArray>):Int{
        var answer=0;
        for(i in 1 until points.size)answer+=maxOf(kotlin.math.abs(points[i][0]-points[i-1][0]),kotlin.math.abs(points[i][1]-points[i-1][1]));
        return answer
    }
}

