class Solution {
    public: int minTimeToVisitAllPoints(vector<vector<int>>& points){
        int answer=0;
        for(int i=1;i<(int)points.size();++i)answer+=max(abs(points[i][0]-points[i-1][0]),abs(points[i][1]-points[i-1][1]));
        return answer;
    }
};
